BEGIN; DO $$ BEGIN IF to_regclass('public.shipment_cancellation_audit') IS NULL THEN RAISE EXCEPTION 'Thieu bang shipment_cancellation_audit. Can cai luong huy phieu an toan truoc.'; END IF; IF to_regprocedure('public.sync_delivery_backlog(uuid)') IS NULL THEN RAISE EXCEPTION 'Thieu RPC sync_delivery_backlog(uuid).'; END IF; IF to_regprocedure('public.inventory_lock_product(uuid)') IS NULL OR to_regprocedure('public.inventory_assert_no_negative_product_after(uuid,date)') IS NULL THEN RAISE EXCEPTION 'Thieu hang rao an toan ton kho.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.cancel_mistaken_shipments_v1(p_shipment_ids uuid[],p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_user_id uuid:=auth.uid(); v_now timestamptz:=now(); v_today date:=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date; v_reason text:=btrim(COALESCE(p_reason,'')); v_ids uuid[]; v_requested_count integer; v_locked_count integer; v_tx_count integer:=0; v_plan record; v_product record; v_actual_qty numeric; BEGIN IF v_user_id IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Chi Admin moi duoc huy phieu tao nham.' USING ERRCODE='42501'; END IF; IF char_length(v_reason)<3 OR char_length(v_reason)>500 THEN RAISE EXCEPTION 'Ly do huy phai tu 3 den 500 ky tu.'; END IF; IF p_shipment_ids IS NULL OR cardinality(p_shipment_ids)=0 OR array_position(p_shipment_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Danh sach phieu can huy khong hop le.'; END IF; SELECT array_agg(x.id ORDER BY x.id),count(*) INTO v_ids,v_requested_count FROM(SELECT DISTINCT unnest(p_shipment_ids) id)x; IF v_requested_count<>cardinality(p_shipment_ids) THEN RAISE EXCEPTION 'Danh sach phieu bi trung lap.'; END IF; IF v_requested_count>100 THEN RAISE EXCEPTION 'Moi lan chi duoc huy toi da 100 phieu.'; END IF; PERFORM 1 FROM public.shipment_logs s WHERE s.id=ANY(v_ids) AND s.deleted_at IS NULL ORDER BY s.id FOR UPDATE; GET DIAGNOSTICS v_locked_count=ROW_COUNT; IF v_locked_count<>v_requested_count THEN RAISE EXCEPTION 'Co phieu khong ton tai hoac da bi huy. Khong phieu nao thay doi.'; END IF; IF EXISTS(SELECT 1 FROM public.shipment_logs s WHERE s.id=ANY(v_ids) AND s.deleted_at IS NULL AND (s.shipment_date<v_today-1 OR s.shipment_date>v_today)) THEN RAISE EXCEPTION 'Chi duoc huy phieu cua hom nay hoac ngay lien truoc. Phieu cu hon can kiem tra rieng.'; END IF; CREATE TEMP TABLE mistaken_cancel_bases ON COMMIT DROP AS SELECT t.id,t.delivery_plan_id,t.product_id,t.tx_date::date tx_date FROM public.inventory_transactions t WHERE t.shipment_id=ANY(v_ids) AND t.adjusted_from_transaction_id IS NULL AND t.deleted_at IS NULL; IF NOT EXISTS(SELECT 1 FROM pg_temp.mistaken_cancel_bases) THEN RAISE EXCEPTION 'Phieu khong con giao dich xuat kho hop le.'; END IF; IF EXISTS(SELECT 1 FROM pg_temp.mistaken_cancel_bases WHERE delivery_plan_id IS NULL) THEN RAISE EXCEPTION 'Phieu co dong xuat kho khong gan ke hoach. Can kiem tra truoc khi huy.'; END IF; CREATE TEMP TABLE mistaken_cancel_plans ON COMMIT DROP AS SELECT DISTINCT delivery_plan_id id FROM pg_temp.mistaken_cancel_bases; PERFORM 1 FROM public.delivery_plans p WHERE p.id IN(SELECT id FROM pg_temp.mistaken_cancel_plans) AND p.deleted_at IS NULL ORDER BY p.id FOR UPDATE; PERFORM next_plan.id FROM public.delivery_plans source_plan JOIN pg_temp.mistaken_cancel_plans affected ON affected.id=source_plan.id JOIN public.delivery_plans next_plan ON next_plan.plan_date=source_plan.plan_date+1 AND next_plan.product_id=source_plan.product_id AND public.delivery_point_key(next_plan.customer_id,next_plan.delivery_customer_id)=public.delivery_point_key(source_plan.customer_id,source_plan.delivery_customer_id) AND next_plan.deleted_at IS NULL WHERE source_plan.deleted_at IS NULL AND source_plan.plan_date<v_today ORDER BY next_plan.id FOR UPDATE OF next_plan; IF EXISTS(SELECT 1 FROM public.delivery_plans source_plan JOIN pg_temp.mistaken_cancel_plans affected ON affected.id=source_plan.id JOIN public.delivery_plans next_plan ON next_plan.plan_date=source_plan.plan_date+1 AND next_plan.product_id=source_plan.product_id AND public.delivery_point_key(next_plan.customer_id,next_plan.delivery_customer_id)=public.delivery_point_key(source_plan.customer_id,source_plan.delivery_customer_id) AND next_plan.deleted_at IS NULL WHERE source_plan.deleted_at IS NULL AND source_plan.plan_date<v_today AND (COALESCE(next_plan.actual_qty,0)>0 OR COALESCE(next_plan.is_completed,false)=true OR EXISTS(SELECT 1 FROM public.inventory_transactions next_tx WHERE next_tx.delivery_plan_id=next_plan.id AND next_tx.tx_type='out' AND next_tx.adjusted_from_transaction_id IS NULL AND next_tx.deleted_at IS NULL))) THEN RAISE EXCEPTION 'Ngay sau da phat sinh giao hang hoac da chot cho ma lien quan. Chua huy phieu de tranh sai No/backlog.'; END IF; PERFORM 1 FROM public.inventory_transactions t WHERE (t.id IN(SELECT id FROM pg_temp.mistaken_cancel_bases) OR t.adjusted_from_transaction_id IN(SELECT id FROM pg_temp.mistaken_cancel_bases)) AND t.deleted_at IS NULL ORDER BY t.id FOR UPDATE; FOR v_product IN SELECT product_id,min(tx_date) tx_date FROM pg_temp.mistaken_cancel_bases GROUP BY product_id ORDER BY product_id LOOP PERFORM public.inventory_lock_product(v_product.product_id); END LOOP; INSERT INTO public.shipment_cancellation_audit(shipment_id,shipment_no_snapshot,shipment_date,reason,cancelled_by,cancelled_at) SELECT s.id,s.shipment_no,s.shipment_date,v_reason,v_user_id,v_now FROM public.shipment_logs s WHERE s.id=ANY(v_ids) AND s.deleted_at IS NULL ORDER BY s.id; PERFORM set_config('app.skip_delivery_backlog_sync','on',true); PERFORM set_config('app.inventory_batch_replace','on',true); UPDATE public.inventory_transactions t SET deleted_at=v_now,deleted_by=v_user_id,updated_at=v_now,updated_by=v_user_id,note=COALESCE(t.note,'')||' | Huy phieu tao nham: '||v_reason WHERE (t.id IN(SELECT id FROM pg_temp.mistaken_cancel_bases) OR t.adjusted_from_transaction_id IN(SELECT id FROM pg_temp.mistaken_cancel_bases)) AND t.deleted_at IS NULL; GET DIAGNOSTICS v_tx_count=ROW_COUNT; FOR v_plan IN SELECT p.* FROM public.delivery_plans p JOIN pg_temp.mistaken_cancel_plans a ON a.id=p.id WHERE p.deleted_at IS NULL ORDER BY p.id LOOP SELECT COALESCE(sum(x.effective_qty),0) INTO v_actual_qty FROM(SELECT b.qty+COALESCE(sum(CASE WHEN adj.tx_type='adjust_in' THEN adj.qty WHEN adj.tx_type='adjust_out' THEN -adj.qty ELSE 0 END),0) effective_qty FROM public.inventory_transactions b LEFT JOIN public.inventory_transactions adj ON adj.adjusted_from_transaction_id=b.id AND adj.deleted_at IS NULL AND adj.tx_type IN('adjust_in','adjust_out') WHERE b.delivery_plan_id=v_plan.id AND b.tx_type='out' AND b.adjusted_from_transaction_id IS NULL AND b.deleted_at IS NULL GROUP BY b.id,b.qty)x; UPDATE public.delivery_plans SET actual_qty=COALESCE(v_actual_qty,0),is_completed=false,updated_at=v_now,updated_by=v_user_id WHERE id=v_plan.id; END LOOP; UPDATE public.shipment_logs SET deleted_at=v_now,note=COALESCE(note,'')||' | Huy phieu tao nham: '||v_reason WHERE id=ANY(v_ids) AND deleted_at IS NULL; PERFORM set_config('app.inventory_batch_replace','off',true); FOR v_product IN SELECT product_id,min(tx_date) tx_date FROM pg_temp.mistaken_cancel_bases GROUP BY product_id ORDER BY product_id LOOP PERFORM public.inventory_assert_no_negative_product_after(v_product.product_id,v_product.tx_date); END LOOP; PERFORM set_config('app.skip_delivery_backlog_sync','off',true); FOR v_plan IN SELECT id FROM pg_temp.mistaken_cancel_plans ORDER BY id LOOP PERFORM public.sync_delivery_backlog(v_plan.id); END LOOP; RETURN jsonb_build_object('success',true,'shipment_count',v_requested_count,'soft_deleted_tx_count',v_tx_count,'reason',v_reason,'message','Da huy phieu tao nham cua hom nay hoac ngay lien truoc. Lich su van duoc giu lai.'); EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.inventory_batch_replace','off',true); PERFORM set_config('app.skip_delivery_backlog_sync','off',true); RAISE; END $$; REVOKE ALL ON FUNCTION public.cancel_mistaken_shipments_v1(uuid[],text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cancel_mistaken_shipments_v1(uuid[],text) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
